/**
 * Accepts a JSON array of fact objects (or `{ "facts": [...] }`) and queues
 * each valid one as a Stage-1 moderation review (a system import — this
 * loads the moderation queue, it does not publish facts directly). Protected
 * by the `X-API-Key` header (ADMIN_API_KEY secret). Supports `?dryRun=true`
 * to validate without writing.
 * @summary Bulk-import facts for moderation (API key required)
 */
export const bulkImportFacts = async (
  bulkImportFactsBody: BulkImportFactsBody,
  params?: BulkImportFactsParams,
  options?: Parameters<typeof customFetch>[1],
): Promise<BulkImportFactsResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<BulkImportFactsResponse>(getBulkImportFactsUrl(params), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(bulkImportFactsBody),
  });
};

export const getBulkImportFactsMutationKey = () => ["bulkImportFacts"] as const;

export const getBulkImportFactsMutationOptions = <
  TError = ErrorType<ErrorEnvelope>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof bulkImportFacts>>,
    TError,
    BulkImportFactsMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof bulkImportFacts>>,
  TError,
  BulkImportFactsMutationVariables,
  TContext
> => {
  const mutationKey = getBulkImportFactsMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof bulkImportFacts>>,
    BulkImportFactsMutationVariables
  > = (props) => {
    const { data, params } = props ?? {};

    return bulkImportFacts(data, params, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

